1	package zkcircuit
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync"
12	)
13	
14	// on-disk layout inside the data directory:
15	//
16	//	data.json    – the committed state (JSON envelope, atomically replaced)
17	//	data.json.tmp– staging file for the next commit (rename(2) target)
18	//	lock         – flock file serializing concurrent processes
19	//
20	// The envelope carries an explicit format version: files written by an
21	// incompatible future build are refused rather than silently migrated or
22	// overwritten.
23	const (
24		dirDataFile = "data.json"
25		dirTmpFile  = "data.json.tmp"
26		dirLockFile = "lock"
27	
28		// FormatVersion is the on-disk format this build writes and accepts.
29		FormatVersion = 1
30	)
31	
32	// envelope is the persisted state container.
33	type envelope struct {
34		Format    int               `json:"format"`
35		Circuits  []persistCircuit  `json:"circuits"`
36		Setups    []persistSetup    `json:"setups"`
37		Jobs      []persistJob      `json:"jobs"`
38		Artifacts []persistArtifact `json:"artifacts,omitempty"`
39	}
40	
41	type persistTerm struct {
42		Wire  int    `json:"wire"`
43		Coeff string `json:"coeff"`
44	}
45	
46	type persistConstraint struct {
47		A []persistTerm `json:"a"`
48		B []persistTerm `json:"b"`
49		C []persistTerm `json:"c"`
50	}
51	
52	// persistDefinition is the canonical, already-validated constraint set bound
53	// to one circuit version. The public/private partition is owned by the
54	// circuit record and is deliberately not duplicated here, so it can never
55	// drift from the declared counts.
56	type persistDefinition struct {
57		Modulus     string              `json:"modulus"`
58		Constraints []persistConstraint `json:"constraints"`
59	}
60	
61	// persistArtifact is a compiled artifact: the version's identity and
62	// constraint count bound to its recomputable SHA-256 hash.
63	type persistArtifact struct {
64		Name        string `json:"name"`
65		Version     int    `json:"version"`
66		Modulus     int64  `json:"modulus"`
67		Constraints int    `json:"constraints"`
68		Hash        string `json:"hash"`
69	}
70	
71	type persistCircuit struct {
72		Name          string             `json:"name"`
73		Version       int                `json:"version"`
74		Constraints   int                `json:"constraints"`
75		PublicInputs  int                `json:"public_inputs"`
76		PrivateInputs int                `json:"private_inputs"`
77		Frozen        bool               `json:"frozen"`
78		Description   string             `json:"description"`
79		Definition    *persistDefinition `json:"definition,omitempty"`
80	}
81	
82	type persistSetup struct {
83		Name    string `json:"name"`
84		Version int    `json:"version"`
85	}
86	
87	type persistJob struct {
88		ID       string `json:"id"`
89		Circuit  string `json:"circuit"`
90		Version  int    `json:"version"`
91		Kind     string `json:"kind"`
92		Attempt  int    `json:"attempt"`
93		Artifact string `json:"artifact,omitempty"`
94		// CompiledHash is the optional binding to the pinned version's compiled
95		// artifact, stored exactly as submitted.
96		CompiledHash string `json:"compiled_hash,omitempty"`
97	}
98	
99	// Store is a persistent workbench backed by one local data directory.
100	//
101	// All operations are safe for concurrent use by multiple goroutines and by
102	// several processes pointed at the same directory: an in-process mutex plus a
103	// process-shared flock serialize commits, and every commit is an atomic
104	// temp-file/fsync/rename replacement. Open the directory with Open and call
105	// Close when done.
106	type Store struct {
107		dir  string
108		mu   sync.Mutex
109		lock *os.File
110	
111		data envelope
112	}
113	
114	// Open opens (creating if needed) the workbench data in dir. If the
115	// directory does not exist it is created. Existing committed data is loaded
116	// and fully validated before Open returns; on a corrupt, truncated or
117	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
118	// leaves every file in the directory untouched.
119	func Open(dir string) (*Store, error) {
120		if dir == "" {
121			return nil, invalidf("data directory must not be empty")
122		}
123		if err := os.MkdirAll(dir, 0o755); err != nil {
124			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
125		}
126		lockPath := filepath.Join(dir, dirLockFile)
127		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
128		if err != nil {
129			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
130		}
131		// Serialize against other processes while we read / validate.
132		if err := lockExclusive(lock); err != nil {
133			lock.Close()
134			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
135		}
136	
137		s := &Store{dir: dir, lock: lock}
138		if err := s.loadLocked(); err != nil {
139			unlockLock(lock)
140			lock.Close()
141			return nil, err
142		}
143		// The lock is taken again per operation; holding it for the store's
144		// lifetime would forbid two open handles on one directory.
145		if err := unlockLock(lock); err != nil {
146			lock.Close()
147			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
148		}
149		return s, nil
150	}
151	
152	// Close releases the directory lock. It does not discard committed data.
153	func (s *Store) Close() error {
154		s.mu.Lock()
155		defer s.mu.Unlock()
156		if s.lock == nil {
157			return nil
158		}
159		var first error
160		if err := unlockLock(s.lock); err != nil {
161			first = err
162		}
163		if err := s.lock.Close(); err != nil && first == nil {
164			first = err
165		}
166		s.lock = nil
167		return first
168	}
169	
170	// Dir reports the data directory backing the store.
171	func (s *Store) Dir() string { return s.dir }
172	
173	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
174	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
175	
176	// loadLocked reads and validates the committed file. Caller must hold the
177	// exclusive flock; the in-process mutex is taken by the public Open path.
178	func (s *Store) loadLocked() error {
179		raw, err := os.ReadFile(s.dataPath())
180		if errors.Is(err, os.ErrNotExist) {
181			s.data = envelope{Format: FormatVersion}
182			return nil
183		}
184		if err != nil {
185			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
186		}
187		if len(strings.TrimSpace(string(raw))) == 0 {
188			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
189		}
190	
191		var env envelope
192		if err := json.Unmarshal(raw, &env); err != nil {
193			// Shape failures surfaced by the persisted-definition decoders are
194			// integrity failures, not JSON syntax errors; report their detail
195			// instead of the generic "not valid JSON" wording.
196			var se StoreError
197			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
198				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
199			}
200			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
201		}
202		if env.Format == 0 {
203			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
204		}
205		if env.Format != FormatVersion {
206			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
207				s.dataPath(), env.Format, FormatVersion)
208		}
209		if err := validateEnvelope(env); err != nil {
210			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
211		}
212		s.data = env
213		return nil
214	}
215	
216	// commitLocked writes the pending state atomically: temp file → fsync →
217	// rename → fsync directory. Caller must hold both the in-process mutex and
218	// the exclusive flock; all in-memory mutations must already have happened and
219	// been rule-checked, so a failure here occurs before any success is reported.
220	func (s *Store) commitLocked() error {
221		s.data.Format = FormatVersion
222		// Stable output: records are stored sorted so files are deterministic.
223		sortEnvelope(&s.data)
224	
225		payload, err := json.MarshalIndent(&s.data, "", "  ")
226		if err != nil {
227			return fmt.Errorf("cannot encode data: %w", err)
228		}
229		payload = append(payload, '\n')
230	
231		tmp := s.tmpPath()
232		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
233		if err != nil {
234			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
235		}
236		if _, err := f.Write(payload); err != nil {
237			f.Close()
238			os.Remove(tmp)
239			return fmt.Errorf("cannot write staged data: %w", err)
240		}
241		if err := f.Sync(); err != nil {
242			f.Close()
243			os.Remove(tmp)
244			return fmt.Errorf("cannot flush staged data: %w", err)
245		}
246		if err := f.Close(); err != nil {
247			os.Remove(tmp)
248			return fmt.Errorf("cannot finish staged data: %w", err)
249		}
250		if err := os.Rename(tmp, s.dataPath()); err != nil {
251			os.Remove(tmp)
252			return fmt.Errorf("cannot commit data file: %w", err)
253		}
254		if err := syncDir(s.dir); err != nil {
255			// The rename already happened; lack of dir fsync only weakens crash
256			// durability, never correctness of what is visible now.
257			return nil
258		}
259		return nil
260	}
261	
262	// withLock runs fn under the in-process mutex and an exclusive flock, then
263	// atomically commits when fn requests it. The on-disk state is re-read after
264	// acquiring the lock, so concurrent commits from another process or another
265	// handle are always observed. Operations validate before mutating; a rejected
266	// operation (commit=false or an error) writes nothing and leaves committed
267	// state unchanged.
268	func (s *Store) withLock(fn func() (commit bool, err error)) error {
269		s.mu.Lock()
270		defer s.mu.Unlock()
271		if s.lock == nil {
272			return invalidf("store is closed")
273		}
274		if err := lockExclusive(s.lock); err != nil {
275			return fmt.Errorf("cannot lock data directory: %w", err)
276		}
277		defer unlockLock(s.lock)
278	
279		if err := s.loadLocked(); err != nil {
280			return err
281		}
282		commit, err := fn()
283		if err != nil {
284			return err
285		}
286		if !commit {
287			return nil
288		}
289		return s.commitLocked()
290	}
291	
292	// withLockRead runs fn under a shared flock over freshly reloaded state.
293	func (s *Store) withLockRead(fn func() error) error {
294		s.mu.Lock()
295		defer s.mu.Unlock()
296		if s.lock == nil {
297			return invalidf("store is closed")
298		}
299		if err := lockShared(s.lock); err != nil {
300			return fmt.Errorf("cannot lock data directory: %w", err)
301		}
302		defer unlockLock(s.lock)
303		if err := s.loadLocked(); err != nil {
304			return err
305		}
306		return fn()
307	}
308	
309	func sortEnvelope(env *envelope) {
310		sort.Slice(env.Circuits, func(i, j int) bool {
311			if env.Circuits[i].Name != env.Circuits[j].Name {
312				return env.Circuits[i].Name < env.Circuits[j].Name
313			}
314			return env.Circuits[i].Version < env.Circuits[j].Version
315		})
316		sort.Slice(env.Setups, func(i, j int) bool {
317			if env.Setups[i].Name != env.Setups[j].Name {
318				return env.Setups[i].Name < env.Setups[j].Name
319			}
320			return env.Setups[i].Version < env.Setups[j].Version
321		})
322		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
323		sort.Slice(env.Artifacts, func(i, j int) bool {
324			if env.Artifacts[i].Name != env.Artifacts[j].Name {
325				return env.Artifacts[i].Name < env.Artifacts[j].Name
326			}
327			return env.Artifacts[i].Version < env.Artifacts[j].Version
328		})
329	}
330	
331	// validateEnvelope re-checks every invariant on load so a tampered or
332	// hand-edited file cannot bypass the domain rules.
333	func validateEnvelope(env envelope) error {
334		seenCircuit := make(map[[2]string]bool)
335		circuitOK := make(map[[2]string]bool)
336		for i, c := range env.Circuits {
337			key := [2]string{c.Name, itoa(c.Version)}
338			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
339				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
340			}
341			if c.Version <= 0 {
342				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
343			}
344			if seenCircuit[key] {
345				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
346			}
347			seenCircuit[key] = true
348			if c.Constraints <= 0 {
349				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
350			}
351			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
352				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
353			}
354			if c.Definition != nil {
355				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
356					return err
357				}
358			}
359			circuitOK[key] = true
360		}
361		seenSetup := make(map[[2]string]bool)
362		for i, p := range env.Setups {
363			key := [2]string{p.Name, itoa(p.Version)}
364			if !circuitOK[key] {
365				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
366			}
367			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
368			if c == nil || !c.Frozen {
369				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
370			}
371			if seenSetup[key] {
372				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
373			}
374			seenSetup[key] = true
375		}
376		seenJob := make(map[string]bool)
377		for i, j := range env.Jobs {
378			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
379				return fmt.Errorf("job #%d has an empty or blank id", i+1)
380			}
381			if seenJob[j.ID] {
382				return fmt.Errorf("job %q appears more than once", j.ID)
383			}
384			seenJob[j.ID] = true
385			if j.Kind != "prove" {
386				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
387			}
388			if j.Attempt <= 0 {
389				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
390			}
391			key := [2]string{j.Circuit, itoa(j.Version)}
392			if !circuitOK[key] {
393				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
394			}
395			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
396			if c == nil || !c.Frozen {
397				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
398			}
399			if !seenSetup[key] {
400				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
401			}
402			// A recorded compiled-artifact binding must still resolve against the
403			// pinned version's artifact; a dangling or mismatched binding makes
404			// the file unreadable rather than silently dropping the binding.
405			if j.CompiledHash != "" {
406				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
407				if artifact == nil {
408					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
409				}
410				if artifact.Hash != j.CompiledHash {
411					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
412						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
413				}
414			}
415		}
416		seenArtifact := make(map[[2]string]bool)
417		for i, a := range env.Artifacts {
418			key := [2]string{a.Name, itoa(a.Version)}
419			if !circuitOK[key] {
420				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
421			}
422			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
423			if c == nil || !c.Frozen {
424				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
425			}
426			if seenArtifact[key] {
427				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
428			}
429			seenArtifact[key] = true
430			if c.Definition == nil {
431				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
432			}
433			if a.Constraints != c.Constraints {
434				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
435					a.Name, a.Version, a.Constraints, c.Constraints)
436			}
437			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
438			if err != nil {
439				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
440			}
441			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
442				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
443			}
444			wantHash := artifactHash(a.Name, a.Version, def)
445			if a.Hash != wantHash {
446				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
447					a.Name, a.Version, a.Hash, wantHash)
448			}
449		}
450		return nil
451	}
452	
453	// validatePersistDefinition re-validates a stored definition against its
454	// version's declared counts: prime modulus, in-range wires and an exact
455	// constraint count match.
456	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
457		parsed, err := definitionFromPersist(*def, public, private)
458		if err != nil {
459			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
460		}
461		if !parsed.compatibleWith(constraints, public, private) {
462			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
463		}
464		return nil
465	}
466	
467	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
468		for i := range cs {
469			if cs[i].Name == name && cs[i].Version == version {
470				return &cs[i]
471			}
472		}
473		return nil
474	}
475	
476	func itoa(v int) string { return fmt.Sprintf("%d", v) }
