1	package zkcircuit
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9	)
10	
11	// These tests pin the read-time contract for a constraint definition that is
12	// already committed in data.json: its required fields and their types must
13	// match what the importer writes. A missing field or a null must never be
14	// read as a legitimate zero value (an empty side array, wire 0), because the
15	// two cases are indistinguishable after a plain struct decode even though
16	// only the first is a real definition.
17	
18	// readGenericEnv loads data.json as a generic JSON value so a test can
19	// damage individual fields without relying on byte offsets.
20	func readGenericEnv(t *testing.T, dir string) map[string]any {
21		t.Helper()
22		raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
23		if err != nil {
24			t.Fatal(err)
25		}
26		var env map[string]any
27		if err := json.Unmarshal(raw, &env); err != nil {
28			t.Fatal(err)
29		}
30		return env
31	}
32	
33	func writeGenericEnv(t *testing.T, dir string, env map[string]any) []byte {
34		t.Helper()
35		raw, err := json.MarshalIndent(env, "", "  ")
36		if err != nil {
37			t.Fatal(err)
38		}
39		raw = append(raw, '\n')
40		if err := os.WriteFile(filepath.Join(dir, dirDataFile), raw, 0o644); err != nil {
41			t.Fatal(err)
42		}
43		return raw
44	}
45	
46	// firstDefinition walks to the first circuit's definition object.
47	func firstDefinition(t *testing.T, env map[string]any) map[string]any {
48		t.Helper()
49		circuit := env["circuits"].([]any)[0].(map[string]any)
50		def, ok := circuit["definition"].(map[string]any)
51		if !ok {
52			t.Fatalf("seeded circuit has no definition object: %v", circuit["definition"])
53		}
54		return def
55	}
56	
57	// TestCorruptPersistedDefinitionRefused damages each required field in turn
58	// and requires Open to refuse the whole directory. The judgment must not
59	// depend on the version being frozen or already compiled, so every shape is
60	// damaged against both a draft (never compiled) and a frozen+compiled store.
61	func TestCorruptPersistedDefinitionRefused(t *testing.T) {
62		const goodDef = `{"modulus":"7","constraints":[
63			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`
64	
65		tamperDef := func(mut func(def map[string]any)) func(map[string]any) {
66			return func(env map[string]any) { mut(firstDefinition(t, env)) }
67		}
68		setSideTerm := func(side string, mut func(term map[string]any)) func(map[string]any) {
69			return tamperDef(func(def map[string]any) {
70				con := def["constraints"].([]any)[0].(map[string]any)
71				term := con[side].([]any)[0].(map[string]any)
72				mut(term)
73			})
74		}
